// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) internal {
        uint64 beforeNumber;
        try c.number() returns (uint64 __r) { beforeNumber = __r; } catch { return; }
        uint64 beforeTimestamp;
        try c.timestamp() returns (uint64 __r) { beforeTimestamp = __r; } catch { return; }
        uint256 beforeBasefee;
        try c.basefee() returns (uint256 __r) { beforeBasefee = __r; } catch { return; }
        bytes32 beforeHash;
        try c.hash() returns (bytes32 __r) { beforeHash = __r; } catch { return; }
        uint64 beforeSequence;
        try c.sequenceNumber() returns (uint64 __r) { beforeSequence = __r; } catch { return; }
        bytes32 beforeBatcher;
        try c.batcherHash() returns (bytes32 __r) { beforeBatcher = __r; } catch { return; }
        uint256 beforeOverhead;
        try c.l1FeeOverhead() returns (uint256 __r) { beforeOverhead = __r; } catch { return; }
        uint256 beforeScalar;
        try c.l1FeeScalar() returns (uint256 __r) { beforeScalar = __r; } catch { return; }
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {} catch { return; }
        assertTrue(c.number() == beforeNumber &&
            c.timestamp() == beforeTimestamp &&
            c.basefee() == beforeBasefee &&
            c.hash() == beforeHash &&
            c.sequenceNumber() == beforeSequence &&
            c.batcherHash() == beforeBatcher &&
            c.l1FeeOverhead() == beforeOverhead &&
            c.l1FeeScalar() == beforeScalar);
    }

    function testFuzz_run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        _run(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
    }

    receive() external payable {}
}
